static void detector_damage_census(void){static int last_hp[2]={-1,-1},last_x[2],last_y[2],last_slot[2]={-1,-1};int slots[]={48,tracked_detector};for(int k=0;k<2;k++){int slot=slots[k];if(slot<0||slot>=MAX_UNITS)continue;int live=u[slot].alive&&u[slot].owner==SIDE&&u[slot].raw_type==42;if(slot!=last_slot[k]){last_slot[k]=slot;last_hp[k]=-1;}if(live){int hp=u[slot].hp;if(last_hp[k]>=0&&hp<last_hp[k]){printf("DETECTOR_DAMAGE frame%d slot%d raw%d owner%d hp%d previous%d xy%d,%d\n",frame,slot,u[slot].raw_type,u[slot].owner,hp,last_hp[k],u[slot].x,u[slot].y);for(int j=0;j<MAX_UNITS;j++)if(u[j].alive&&u[j].owner==ENEMY&&dist2(u[j].x,u[j].y,u[slot].x,u[slot].y)<512*512)printf("NEAR_HOSTILE frame%d slot%d raw%d owner%d hp%d xy%d,%d cd%d target%d order%d\n",frame,j,u[j].raw_type,u[j].owner,u[j].hp,u[j].x,u[j].y,u[j].cd,u[j].target,u[j].order);}last_hp[k]=hp;last_x[k]=u[slot].x;last_y[k]=u[slot].y;}else if(last_hp[k]>0){printf("DETECTOR_REMOVED frame%d slot%d last_hp%d last_xy%d,%d\n",frame,slot,last_hp[k],last_x[k],last_y[k]);for(int j=0;j<MAX_UNITS;j++)if(u[j].alive&&u[j].owner==ENEMY&&dist2(u[j].x,u[j].y,last_x[k],last_y[k])<512*512)printf("NEAR_HOSTILE frame%d slot%d raw%d owner%d hp%d xy%d,%d cd%d target%d order%d\n",frame,j,u[j].raw_type,u[j].owner,u[j].hp,u[j].x,u[j].y,u[j].cd,u[j].target,u[j].order);last_hp[k]=0;}}}

